INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(8500, 0, 85, 0, 0, 0, 'Tirisfal Glades', 'Tirisfal Glades was once the heartland of the kingdom of Lordaeron, a country of misty woods, quiet farms and noble estates in the shadow of the royal capital. When the Plague of Undeath swept through, so many died that mass graves had to be dug, and much of the population rose again as servants of the Scourge. Now the glades belong to the Forsaken, the undead who broke free of the Lich King under Lady Sylvanas Windrunner. From the Undercity beneath the ruined capital and from the town of Brill, the Deathguard fight on several fronts at once. Mindless dead still shamble through Deathknell and hold the Agamand Mills, Rot Hide gnolls rob the graves for the Lich King, and more undead slip in past the Bulwark from the Plaguelands. In the northeast the Scarlet Crusade holds its great monastery and sends zealots across the glades to purge every undead they find, free-willed or not.', 'warcraft.wiki.gg/wiki/Tirisfal_Glades (pre-Cataclysm history: part of Lordaeron, mass graves, Forsaken claim the glades, Scarlet Monastery); quest 363 reward text (freed by Lady Sylvanas); quest 364 description; quest 358 description; quests 356, 359 (Scourge slipping past the Bulwark); quest 381 description (Crusade will not rest until every undead, Scourge or no, is destroyed); quest 426 description'),
(8501, 1, 85, 1, 0, 0, 'Deathknell', 'In the hills of western Tirisfal lies Deathknell, where many of the Forsaken first open their eyes to their new existence. The newly risen wake in the crypt above the village, the Shadow Grave, tended by its caretaker Undertaker Mordo, who is ready to toss onto the fire any who fail to stir. Down the road in the chapel, Shadow Priest Sarvis explains to each confused arrival that the Dark Lady has freed them from the Lich King. Executor Arren commands the village, Deathguard Saltain sends recruits to scavenge for usable gear, and Novice Elreth tends the wounded. Mindless zombies and ghouls, their former kin, still wander the northern streets, and a Scarlet Crusade detachment has camped to the southeast.', 'quest 363 description and reward text (Mordo, caretaker of the crypt; toss you into the fire); warcraft.wiki.gg/wiki/Shadow_Grave (pre-Cataclysm undead characters came to life there); quests 364, 3902, 376, 381 descriptions; warcraft.wiki.gg/wiki/Deathknell (Arren leads the village; Scarlet camp southeast); posarea: Mordo 1568, Sarvis 1569, Arren 1570 all in area 154; WMOAreaTable.dbc (2117 Shadow Grave is a WMO area); playercreateinfo race 5 start position'),
(8502, 1, 85, 2, 0, 0, 'Night Web''s Hollow', 'Northwest of Deathknell lies Night Web''s Hollow, a small valley around the mouth of an old gold mine. Gold was scarce even when the Alliance stood at the height of its power, and the Forsaken badly need the ore, but spiders have overrun the valley and the tunnels alike. Young spiders prowl the open ground while larger night webs lurk in the shadowed depths of the mine. Executor Arren can spare few hands for the work, so the hollow is being cleared bit by bit. He expects weeks or months to pass before the infestation is gone and the webbing can finally be burned away with torches.', 'quest 380 description, reward and request texts; warcraft.wiki.gg/wiki/Night_Web''s_Hollow (gold mine northwest of Deathknell, young spiders outside, adults within); posarea: Young Night Web Spider 1504 and Night Web Spider 1505 in area 155'),
(8503, 1, 85, 3, 0, 0, 'Solliden Farmstead', 'North of Deathknell, the Solliden Farmstead is a rare sight in Tirisfal: a farm still worked by living humans. Farmer Solliden and his hands tend their pumpkin fields with the Scarlet Crusade close by, its warriors holding a tower to the west beyond the farm, and the farmers side with the Crusaders against all undead. To the Forsaken they are a blight on the land. Deathguard Simmer keeps watch on the road nearby and sends young recruits to steal the farm''s pumpkins, which the Royal Apothecary Society in Brill has found a sinister use for.', 'quest 365 description (farm north of Deathknell, Scarlet Crusade patrols from their tower, steal pumpkins for Apothecary Johaan); quest 427 description (tower past the Solliden Farmstead); quest 407 (laced pumpkin); creature_template: Farmer Solliden 1936, Tirisfal Farmer 1934, Farmhand 1935 use faction 67 (Scarlet Crusade); posarea: Tirisfal Farmer spawns in area 156; Scarlet Warriors west of it; warcraft.wiki.gg/wiki/Solliden_Farmstead'),
(8504, 1, 85, 4, 0, 0, 'Cold Hearth Manor', 'Cold Hearth Manor stands beside the main road southwest of Brill, just across a bridge. It was once a farm known for its welcoming hearth and bountiful crops, but the Plague killed everyone who lived and worked there, and its fields have long since gone barren. The Forsaken have taken over the farmhouse, where the tailors Bowen and Constance Brisboise ply their trade for passing travelers. The country around it is far from safe. Rotting dead and ravaged corpses have trickled into the lands west of Brill near the old bridge, and the Deathguard reward those who beat them back.', 'warcraft.wiki.gg/wiki/Cold_Hearth_Manor (warm atmosphere and bountiful crops, Plague killed all, Forsaken took over the farmhouse and trade with travelers); npc_text 4093 (Bowen''s house southwest of Brill just over the bridge at Cold Hearth Manor); quest 383 description (road passes Cold Hearth Manor); quest 404 description; posarea: Bowen 3523, Constance 3522, Rotting Dead 1525 and Ravaged Corpse 1526 spawns in area 166'),
(8505, 1, 85, 5, 0, 0, 'Brill', 'Brill was a human town of the Lordaeron countryside and one of the first to fall to the Plague of Undeath. Today it is the main Forsaken town of the glades, just north of the ruined capital. Magistrate Sevren governs from the town hall, while Executor Zygand directs the Deathguard against the Scourge and the Scarlet Crusade. Apothecaries pursue their experiments, a wanted poster calls for the death of the gnoll Maggot Eye, and the Gallows'' End Tavern serves as inn and prison both. North of the town, near the graveyard, stands a sealed mausoleum where the Deathguard hold Ulag the Cleaver, a captured Scourge agent still in thrall to the Lich King.', 'warcraft.wiki.gg/wiki/Brill (human town, one of the earliest afflicted by the Plague; pre-Cataclysm features); npc_text 4074 (Ruins of Lordaeron to the south); quests 358, 427, 367 (Sevren, Zygand, Johaan); gameobject 711 Wanted! in Brill; quest 398; quests 407, 492 (tavern cellar prisoners); quest 1819 description (Ulag, skull stone trigger near the mausoleum to the north); gameobjects 104593 Mausoleum Trigger and 103813 Mausoleum Seal at 59,48'),
(8506, 1, 85, 6, 0, 0, 'Gallows'' End Tavern', 'The Gallows'' End Tavern stands on the southeast edge of Brill. Innkeeper Renee offers the weary dead a place to rest their bones, a mage trainer who checked in too late to get a room teaches from the upstairs landing, and Coleman Farthing nurses his bitter grudge against the Agamand family. The cellar has a grimmer purpose. The Deathguard keep prisoners there until they can be properly dealt with, among them a Scarlet zealot and a dwarven mountaineer, and the apothecaries of Brill find such captives convenient subjects for testing their latest brews.', 'npc_text 4077, 4081, 4085 (tavern on the southeast end of Brill; Cain Firesong on the landing, too late to get a room); npc_text 821 and quest 8 completion text (Renee); quest 1820 description (Coleman in the Gallows'' End Tavern); quest 492 description (cellar as holding cell until prisoners are properly dealt with); quest 407 description'),
(8507, 1, 85, 7, 0, 0, 'Agamand Mills', 'Northwest of Brill, a cluster of windmills marks the Agamand Mills, once the seat of the most prosperous family in Tirisfal. When the Scourge came, the Agamands fortified their home and persuaded their workers to stay and defend it. The defense failed, and the family and their people perished. Now the Scourge mean to make the mills a base for further attacks on the Forsaken. Skeletal soldiers and darkeye bonecasters crowd the fields, lost souls drift among the windmills, and the dead Agamands themselves walk the grounds as minions of the Lich King.', 'quest 354 description; quest 426 description; page_text 252-254 (Thurman''s letter: Devlin''s betrayal); warcraft.wiki.gg/wiki/Agamand_Mills (pre-Cataclysm section); posarea: Gregor 1654, Devlin 1657, Dargol 1658 in area 157; DB spawns Rattlecage Soldier, Cracked Skull Soldier, Darkeye Bonecaster, Lost Soul there'),
(8508, 1, 85, 8, 0, 0, 'Agamand Family Crypt', 'At the north end of the Agamand Mills stands the family crypt, where generations of Agamands were laid to rest. It is now the strongest Scourge position in the area and the headquarters of Captain Dargol, a skeletal commander who uses necromancy to raise the Agamand ancestors from their tombs. Wailing and rotting dead fill the grounds, ready to be turned against the Forsaken. The crypt also guards the family''s heirloom weapons, a sword, an axe, a dagger and a mace, which Coleman Farthing would dearly like to see stripped from the cursed Agamand lands.', 'quest 408 description; quest 1821 description and reward text; DB: Wailing Ancestor 1534 and Rotting Ancestor 1530 spawns around 52,28; Captain Dargol 1658 at 52.8,26.3'),
(8509, 1, 85, 9, 0, 0, 'Garren''s Haunt', 'North of Brill, Garren''s Haunt was once a prosperous farmstead of farmhouse, barn and wide fields. The Scourge murdered Garren and his family when Lordaeron fell, and the gray, lifeless farm is now the den of the Rot Hide gnolls, corpse thieves in the service of the Scourge who attack anyone who strays too close. The foulest of them is Maggot Eye. To the southwest lie the mass graves dug for the countless dead of the Plague, and the gnolls dig there for bodies to carry off and swell the Lich King''s armies.', 'warcraft.wiki.gg/wiki/Garren''s_Haunt (pre-Cataclysm section: prosperous farm, Garren and family murdered, Rot Hides and Maggot Eye); quest 358 description (mass graves southwest of Garren''s Haunt); quest 398 description; posarea: Maggot Eye 1753 in area 164'),
(8510, 1, 85, 10, 0, 0, 'Gunther''s Retreat', 'On an island in Brightwater Lake, northeast of Brill, a lone lich has made his home at Gunther''s Retreat. He is free of the Lich King''s will, yet believes every other undead is still a Scourge slave, and he sets his minions on anyone who approaches, Forsaken included. Hungering dead and shambling horrors guard the island. Off its southern shore stands an old, bloody table used as an altar by Lillith Nefara, a powerful agent of the Scourge, who wakes in wrath when a Candle of Beckoning is lit upon it.', 'quest 357 description (lich on the island in Brightwater Lake; believes all other undead are Scourge slaves); quest 409 description; creature_text 1946; gameobject 1557 Lillith''s Dinner Table, 1586 Crate of Candles; posarea: Gunther 1497 and Hungering Dead 1527 in area 163, Lillith''s table in area 162; warcraft.wiki.gg/wiki/Gunther_Arcanus'),
(8511, 1, 85, 11, 0, 0, 'Balnir Farmstead', 'The Balnir Farmstead lies in eastern Tirisfal on the way to the Plaguelands. Its family once bred the white horses ridden by Lordaeron''s royal household. Today the ruined farm is a haven for Scourge that slip past the Bulwark, bleeding horrors and wandering spirits among them, and the Deathguard patrol it closely. Mages of the Undercity gather the snapdragons in its garden, a flower highly receptive to magic, to learn whether the taint of the Plaguelands has crept into Tirisfal.', 'warcraft.wiki.gg/wiki/Balnir_Farmstead (royal horse breeders; Invincible born and buried there; Scourge haven); page_text 3378 and gameobject 192835 (grave plaque) in area 165; quests 356, 359 reward text, 1882 description and request text; posarea: Bleeding Horror 1529, Wandering Spirit 1532 in area 165; quest 1882 completion text (snapdragons highly receptive to magic)'),
(8512, 1, 85, 12, 0, 0, 'Crusader Outpost', 'Crusader Outpost is a ruined tower in eastern Tirisfal near the Balnir Farmstead, held by the Scarlet Crusade to watch the main road through the glades. Its garrison of Scarlet friars answers to Captain Vachon and raids out from the tower against the undead. Executor Zygand of Brill reckons that cutting down the captain and his friars would be a devastating blow to the Crusade in the glades.', 'warcraft.wiki.gg/wiki/Crusader_Outpost (scout tower watching the main road, commanded by Captain Vachon); quest 371 description and reward text; page_text 223, 224 (Tirisfal Regional Command orders); posarea: Captain Vachon 1664 in area 167; Scarlet Friar spawns nearby; quest 371 description (devastating blow)'),
(8513, 1, 85, 13, 0, 0, 'Venomweb Vale', 'Venomweb Vale is a wide valley in eastern Tirisfal, just south of the Scarlet Monastery. It was once a fine hunting ground for deer and rabbits, but it now crawls with vicious night web spiders and takes its new name from them. Their venom is prized by the apothecaries of Brill, who believe it preserves the deadly agent of an ancient plague. The spiders gather around a monstrous one called Sri''skulk. Old tales say the vale was once a meeting place of the Council of Tirisfal, and that one of its members bred the spiders to guard it.', 'warcraft.wiki.gg/wiki/Venomweb_Vale (former hunting ground, spiders led by Sri''skulk, Council of Tirisfal meeting place per the novels); quest 369 description; posarea: Vicious Night Web Spider 1555 and Sri''skulk 10359 in area 812; warcraft.wiki.gg/wiki/Ethylar (Council predecessor created the spiders)'),
(8514, 1, 85, 14, 0, 0, 'Whispering Gardens', 'The Whispering Gardens spread across the hill below the entrance of the Scarlet Monastery, the great seat of the Scarlet Crusade in northeastern Tirisfal. Long ago a fierce battle was fought here between a Scourge host and the forces that would become the Crusade, and it is said the spirits of the fallen still murmur in the twilight. Today the gardens, and the hedged Terrace of Repose on the far side of the monastery doors, are thick with Scarlet scouts, magicians and preservers, who guard the approach to the monastery against undead and outsiders alike.', 'warcraft.wiki.gg/wiki/Whispering_Gardens (hill south of the monastery entrance; battle with the Scourge; faint whispers in the twilight; Terrace of Repose adjacent); npc_text 7206 (Scarlet Monastery in the hills northeast of Tirisfal); posarea: Scarlet Magician 4282, Scarlet Scout 4281, Scarlet Preserver 4280 spawn in areas 160 and 161; warcraft.wiki.gg/wiki/Terrace_of_Repose (just north of the monastery entrance, hedges and fountain)'),
(8515, 1, 85, 15, 0, 0, 'Scarlet Watch Post', 'North of the Scarlet Monastery, the Scarlet Watch Post is a scout tower guarding the monastery''s less defensible northern side. It stands past Faol''s Rest, where the revered Archbishop Alonsus Faol was laid to rest some time before the Plague. The tower''s crew of neophytes and vanguards is led by Captain Melrache, a ruthless commander who keeps two bodyguards at his side and raids across northern Tirisfal.', 'warcraft.wiki.gg/wiki/Scarlet_Watch_Post (scout tower north of the monastery, commanded by Captain Melrache); quest 372 description (ruined tower in northern Tirisfal, past Faol''s Rest, ruthless commander, two bodyguards); page_text 224; warcraft.wiki.gg/wiki/Faol''s_Rest (grave of the much revered archbishop); posarea: Melrache 1665, Scarlet Neophyte 1539, Scarlet Vanguard 1540 in area 459; warcraft.wiki.gg/wiki/Scarlet_Watch_Post'),
(8516, 1, 85, 16, 0, 0, 'Ruins of Lordaeron', 'South of Brill rise the Ruins of Lordaeron, all that remains of the capital where King Terenas Menethil ruled. In its throne room the king was slain by his own son, Prince Arthas, and the Scourge laid the city waste. A grave in the ruins honors Terenas as the last true king of Lordaeron, praying that the father lie blameless for the deeds of the son. Beneath lies the Undercity, capital of the Forsaken, reached by lifts at the back of the ruins, and zeppelins from outside the walls link it with distant lands.', 'warcraft.wiki.gg/wiki/Ruins_of_Lordaeron (throne room where Arthas killed Terenas; Undercity beneath; Battle for the Undercity in Wrath); page_text 1731 and gameobject 175659 Here Lies King Terenas Menethil II, area 153; npc_text 4074 (elevators at the back of the ruins); DB: zeppelin masters Zapetta 9566, Hin Denburg 3150, Meefi Farthrottle 26539 outside the ruins; DB: Thrall 32518, Sylvanas 32365, Vol''jin 31649 at the ruins entrance (Battle for the Undercity); quest 13267 description; creature spawns 32518, 32365 at 1945,234 (area 153)'),
(8517, 1, 85, 17, 0, 0, 'The Bulwark', 'The Bulwark guards the eastern edge of Tirisfal where the road enters the Western Plaguelands, the Forsaken''s last line of defense against the Scourge beyond. High Executor Derrington commands this front, where politics give way to a daily fight for survival and the defenders press toward Andorhal. Members of the Argent Dawn, an order that calls both Horde and Alliance its friends in the war on evil, stand alongside the Forsaken, and apothecaries prepare agents to turn the Scourge''s plague cauldrons against their makers. Even so, some undead still slip past into the glades.', 'warcraft.wiki.gg/wiki/The_Bulwark (Forsaken''s last bastion of defense; Forsaken and Argent Dawn defenders); npc_text 3753 (Derrington); npc_text 4134 (Argent Officer Garush); npc_text 4040 (Shadow Priestess Vandis), quest 5228; quest 359 reward text; posarea: Derrington 10837 in area 152'),
(8518, 2, 85, 1, 2, 0, 'Executor Zygand', 'Executor Zygand commands the Deathguard in Brill, with officers such as Executor Arren at Deathknell and Deathguard Linnea at the eastern waystation reporting to him. With the Lich King''s army growing each night the Deathguard have larger worries, so Zygand looks to recruits with initiative to drive the Scarlet Crusade to the grave. He has little patience for those who idle in Brill while their people need them in the field, and he prizes ruthlessness in those who serve the Dark Lady under him.', 'quest 383 description and reward text (Arren''s superior; kill their leaders); quest 356 reward text (Linnea''s superior); quest 427 description (Lich King''s army grows each night; initiative); quests 370, 371, 372 descriptions and reward texts (ruthless fighters); warcraft.wiki.gg/wiki/Executor_Zygand; quest 370 completion text (no time wasted in Brill)'),
(8519, 2, 85, 2, 2, 0, 'Magistrate Sevren', 'Magistrate Sevren governs Brill from its town hall, a brisk official who keeps the town''s records of the dead and directs its struggle against the Scourge. He relies on fresh reports from the Deathguard waystation near the Plaguelands border, sends agents to stop the Rot Hide gnolls robbing the mass graves, and has marked the Scourge stronghold in the Agamand Family Crypt for destruction. When Bethor Iceshard of the Undercity asked for an agent of proven worth against the Scourge for a dangerous errand, it was Sevren who chose one and sent them south with his orders.', 'warcraft.wiki.gg/wiki/Magistrate_Sevren (Brill Town Hall, known for being brisk); quest 440 description (records of recent deaths); quests 359, 358, 408, 405 descriptions'),
(8520, 2, 85, 3, 2, 0, 'Shadow Priest Sarvis', 'Shadow Priest Sarvis waits in the chapel at the foot of the hill in Deathknell, and for many newly risen Forsaken he is the first to explain what has become of them. He tells each one that Lady Sylvanas has freed them from the Lich King, and that the Forsaken now wage war on the Scourge and on the holdouts of humanity alike. No other race on Azeroth, he says, has suffered as their people have, and laughing in the face of death is now second nature to them. He sends every recruit against the mindless dead of the village, regretting only that such numbers cannot be brought into the fold.', 'quest 363 description and reward text; npc_text 4934 (gossip); quest 364 description and reward text; quest 3901 reward text'),
(8521, 2, 85, 4, 2, 0, 'Gunther Arcanus', 'Gunther Arcanus is the lich of Brightwater Lake, who keeps to his island at Gunther''s Retreat northeast of Brill. He fell to the Plague but has broken free of the Lich King''s hold, and he has grown powerful in death. Yet he believes every other undead is still a Scourge slave, and he sets his minions on all who come near, Forsaken included. To the Forsaken a free-willed lich is well worth winning over, for his knowledge of necromancy could serve the Dark Lady well.', 'quest 366 description (Kirin Tor students; both fell to the Plague); quest 357 description and reward text (skilled necromancer in life); quest 409 description and reward text; quest 411 description; warcraft.wiki.gg/wiki/Gunther_Arcanus (pre-Cataclysm biography)'),
(8522, 2, 85, 5, 2, 0, 'Coleman and Yvette Farthing', 'Coleman Farthing worked the Agamand Mills before the Plague. When the Scourge came, the Agamands fortified their home and talked their workers into staying to defend it, and Coleman, a loyal fool by his own account, was doomed to undeath by their pride. Now a Forsaken at the Gallows'' End Tavern in Brill, he blames the family for all he lost, and since the dead Agamands walk the mills as servants of the Scourge, he wants their remains destroyed and brought to him. His daughter Yvette has risen among the Forsaken too and keeps near him in Brill. Thurman, the eldest Agamand son, was once her beloved.', 'quest 354 description and reward text; quest 362 reward text (bones on my mantle); quest 361 reward text (Yvette); quest 1820 description; warcraft.wiki.gg/wiki/Coleman_Farthing (Yvette listed as his daughter); DB: Coleman 1500 and Yvette 1560 stand together in Brill (2262,244 and 2252,250)'),
(8523, 2, 85, 6, 0, 0, 'Devlin Agamand', 'Devlin was the younger of the two Agamand sons, weak and sharp-tongued where his brother Thurman was tall and gentle. When the Agamand Mills fell to the Plague, Coleman Farthing was not surprised to hear that Devlin was quick to succumb. He now haunts the road to the mills as a servant of the Lich King, and falls on anyone who comes to visit the family. His mad chatter carries on the wind: his family hated him and thought him weak, he is head of the family at last, and he asks his cold lord when the promise will be kept.', 'quest 362 description; page_text 253-255 (Thurman''s letter); creature_text 1657; quest 362 description (quick to succumb; mad chattering near the road)'),
(8524, 2, 85, 7, 2, 0, 'Apothecary Johaan', 'Apothecary Johaan of the Royal Apothecary Society works in Brill on a challenge set by Lady Sylvanas herself: to brew a new plague deadlier than any ailment on Azeroth, one that will bring Arthas''s Scourge to ruin. He proceeds by trial and error, testing darkhound blood, murloc scales and the venom of night web spiders, and lacing ordinary pumpkins with his formulas. His test subjects come from among the prisoners in the cellar of the Gallows'' End Tavern. Mindful of his duty to the Society, he shares his findings with his colleagues at the Sepulcher in Silverpine Forest.', 'quests 367, 368, 369 descriptions; quests 407, 492 descriptions; quest 445 description'),
(8525, 2, 85, 8, 0, 0, 'Maggot Eye', 'Maggot Eye is a gnoll of the Rot Hide pack, foul even by gnoll standards, who pillages the lands around Garren''s Haunt north of Brill. He has been stealing corpses for the Lich King''s armies, and the town of Brill has sentenced him to death for his crimes against the Forsaken. A wanted poster in town promises a reward to whoever carries out the sentence and brings his paw to Executor Zygand, and closes with a blunt reminder that mercy is for the weak.', 'quest 398 description and reward text; gameobject 711 Wanted! in Brill; posarea: Maggot Eye in area 164'),
(8526, 2, 85, 9, 2, 0, 'High Executor Derrington', 'High Executor Derrington commands the Forsaken at the Bulwark on Tirisfal''s eastern border. He has no patience for the schemes of politicians, for at the Bulwark survival is fought for every day, and he welcomes anyone eager to prove themselves a hero. His eyes are fixed on Andorhal and the lich Araj the Summoner who holds it. He plans to set the Scarlet Crusade and the Scourge at each other''s throats with a burned command tent and a planted Scourge banner, and his second, Shadow Priestess Vandis, oversees a scheme to turn the Scourge''s own plague cauldrons against them.', 'npc_text 3753 (gossip); quest 105 description; quest 5096 description; quest 5228 description (My second, Shadow Priestess Vandis)'),
(8527, 3, 85, 1, 2, 0, 'Rude Awakening', 'Each new Forsaken in Deathknell begins in the cold of the crypt, greeted by Undertaker Mordo and sent down to Shadow Priest Sarvis, who explains that the Lich King''s hold is broken and that the Dark Lady leads the war against the Scourge. The first lesson is to destroy the mindless zombies, ghouls and rattling skeletons in the north of the village, former brothers and sisters who remain the Lich King''s slaves. Recruits scavenge the village for gear, and hunt wolves and bats so Novice Elreth can find them armor. Among these first tasks is a gentler one. Marla Fipps was spared undeath only to die at the hands of her husband Samuel, who rose as one of the mindless. Her last wish was to be buried beside him, and Samuel still roams a ruined camp northeast of the village.', 'quests 363, 364, 3901, 3902, 376, 6395 (descriptions and reward texts); gameobject 178090 Marla''s Grave'),
(8528, 3, 85, 2, 2, 0, 'At War with the Scarlet Crusade', 'The Scarlet Crusade hunts every undead in Tirisfal, Scourge or Forsaken, and the Deathguard answer in kind. It begins at Deathknell, where Executor Arren strikes at a Crusade camp to the southeast. Word from Brill says a messenger from the Scarlet Monastery has been sent there with important information, and Arren means to have it. In Brill, Executor Zygand wants recruits with initiative to drive the zealots to the grave, starting with the Scarlet warriors at the tower beyond the Solliden Farmstead. Deathguard Burgess gathers Scarlet insignia rings as proof of loyalty to the Dark Lady and to the dreadlord Varimathras, who, Burgess says, is seeing personally to the destruction of the human race.', 'quests 381, 382, 383, 427, 370, 371, 372, 374 (descriptions and reward texts); page_text 223, 224 (Tirisfal Regional Command, by order of the Highlord); creature_text 1667'),
(8529, 3, 85, 3, 2, 0, 'The Fall of House Agamand', 'The Agamands were the wealthiest family in Tirisfal, and their pride became their ruin. When the Scourge came, Gregor Agamand would not abandon his mills. He fortified his home and talked his workers into staying to fight, and all of them were doomed to undeath. Now the dead Agamands serve the Scourge, who mean to make the mills a base for attacks across Tirisfal, and the Deathguard of Brill send fighters to clear the fields. Coleman Farthing, once a worker at the mills, wants the remains of Gregor, Nissa, Thurman and Devlin Agamand brought to him. Somewhere among the dead at the mills lies a letter from Thurman, the elder son, to Yvette Farthing, which never reached her.', 'quests 354, 355, 361, 362, 408, 426 (descriptions and reward texts); page_text 214, 252-256 (Thurman''s letter); warcraft.wiki.gg/wiki/Agamand_Mills'),
(8530, 3, 85, 4, 2, 0, 'A New Plague', 'Lady Sylvanas has challenged the Royal Apothecary Society to create a new plague, deadlier than any ailment on Azeroth, to bring Arthas''s Scourge to ruin. In Brill, Apothecary Johaan pursues the task by trial and error. He tests the blood of darkhounds, then the scales of murlocs, for plaguing a whole world proves harder than poisoning one victim, and then, after finding an old text about an ancient plague preserved in spider venom, the poison of the vicious night web spiders of eastern Tirisfal. Pumpkins stolen from the Solliden Farmstead serve him too. One, laced with his latest formula, is carried to a starving Scarlet zealot held in the cellar of the Gallows'' End Tavern.', 'quests 365, 407, 367, 368, 369, 492, 445 (descriptions and reward texts); creature_text 1931'),
(8531, 3, 85, 5, 2, 0, 'The Prodigal Lich', 'Bethor Iceshard, a high-ranking mage of the Undercity, asks Magistrate Sevren for an agent of proven worth against the Scourge. Sevren knows only that the task means recruiting a wayward lich, and that it will be dangerous. The lich dwells on an island in Brightwater Lake. He is free-willed, yet believes every other undead a Scourge slave and sets his minions on all who approach. Because he is Forsaken the Dark Lady will want him, and if he is skilled in necromancy his knowledge would be of great use. To learn who he is and what he can do, Bethor needs the lich''s spellbook, so the agent must steal into his camp and take it.', 'quests 405, 357, 366, 409, 411 (descriptions and reward texts); page_text 3479 (Thule sided with the Scourge); quest 446 description; warcraft.wiki.gg/wiki/Gunther_Arcanus; quest 405 description; quest 357 description'),
(8532, 3, 85, 6, 2, 0, 'The Graverobbers', 'When the Plague first came to Tirisfal, the dead were so many that mass graves were dug southwest of Garren''s Haunt. Those bodies have so far been spared undeath, but the Scourge now send the Rot Hide gnolls to dig them up and carry them off to swell the Lich King''s armies. Magistrate Sevren will not allow it. The Rot Hides are hunted at the graves and at Garren''s Haunt, and the embalming ichor that animates them is gathered for study. Brill has also sentenced Maggot Eye, the foulest of the corpse thieves, to death. Nearby, a junior apothecary in the Brill graveyard waits impatiently on an abomination named Gordo, sent out to pick weeds by the graves.', 'quest 358 description and reward text; quest 444 description (warlock and necromantic magics); quest 446 description (Thule leads the Rot Hides); quest 398; quests 5481, 5482 and creature_text 10665; npc_text 15531; quest_template_addon: 444 follows 443 (Silverpine), 446 follows 444');
INSERT INTO `mod_lore_codex_part` (`Entry`, `Part`, `MinState`, `MaxState`, `Body`, `Sources`) VALUES
(8511, 1, 13, 255, 'Among the ruins a small grave marker bears the name of Invincible, the beloved steed of Prince Arthas Menethil. Its words praise the horse as loyal and great of heart while he lived, and wish the devoted friend peace in death, among clear streams and green pastures.', 'page_text 3378 and gameobject 192835 Invincible (grave plaque, guid 364 at 2044,-521, area 165)'),
(8512, 1, 0, 255, 'Documents taken from a Scarlet messenger at Deathknell name Vachon as one of the three captains of the Crusade''s Tirisfal Regional Command. In them his superiors warn of growing undead movement near the northern tower and expect the captain to deal with it quickly and decisively.', 'page_text 223, 224 (Scarlet Crusade Documents: Tirisfal Regional Command, orders to Vachon); quest 382 reward text'),
(8515, 1, 0, 255, 'The documents taken from a Scarlet messenger at Deathknell show Melrache''s place in the Crusade''s Tirisfal Regional Command. His superiors are uneasy at how organized the undead near the borders of the Plaguelands have become, and have promised him a fresh group of men in the coming weeks.', 'page_text 224 (orders to Melrache); quest 382 reward text'),
(8516, 1, 13, 255, 'Of late the zeppelins outside the walls serve the war in the north as well. The Cloudkisser carries the Forsaken across the sea to Vengeance Landing in the Howling Fjord, their foothold on the shores of Northrend.', 'DB: Meefi Farthrottle 26539 Howling Fjord Zeppelin Master at 2058,357 (area 85, outside the ruins), npc_text 12649 (the Cloudkisser to Vengeance Landing); warcraft.wiki.gg/wiki/Vengeance_Landing (Forsaken stronghold in the Howling Fjord, zeppelin to Tirisfal)'),
(8516, 2, 13, 255, 'After the Wrathgate the ruins became a war camp. Varimathras and Putress had betrayed the Dark Lady and seized the city below, and the Horde massed among these broken walls to take it back. Warsong battleguards and siege engines filled the ruins, Vol''jin held the ground for the Warchief, and Thrall and Lady Sylvanas came here to give the order to attack.', 'quest 13266 description (betrayal by Varimathras and Putress; Vol''jin waiting) and reward text (Undercity a war zone); quest 13267 description (soldiers wait for the Warchief''s attack orders); DB phase 64 spawns at the ruins entrance (area 153): Vol''jin 31649, Thrall 32518, Sylvanas 32365, Warsong Battleguard 31739, Horde Demolisher 31652; spell_area 59062 in area 85 from accepting 13266 until 13267'),
(8518, 1, 0, 255, 'Documents taken from a Scarlet messenger at Deathknell give Zygand the names and positions of the Crusade''s officers in Tirisfal, its three captains among them. He muses on the blow the zealots'' morale would suffer if their leaders were killed in one swift strike.', 'quest 383 reward text; page_text 223, 224 (item 2885, carried in 383)'),
(8518, 2, 0, 255, 'When Captain Melrache, the last of the Crusade captains he sent the Deathguard after, falls, Zygand is well pleased. Ruthless fighters who conquer in the name of the Forsaken, he says, bring his people one step closer to defeating Arthas once and for all, and he has a good feeling about the comrade who did the work.', 'quest 372 reward text'),
(8521, 1, 0, 255, 'His spellbook gives away who he was. In life Gunther was a skilled necromancer who studied among the Kirin Tor of Dalaran with his friends Bethor Iceshard and Thule Ravenclaw. Gunther and Bethor both fell to the Plague, while Thule went over to the Scourge. Bethor, free himself and serving the Dark Lady, rejoices to learn that his old friend is free too.', 'quest 357 reward text; quest 366 description'),
(8521, 2, 0, 255, 'The book comes back to Gunther bearing a new enchantment, and he knows it for Bethor''s work. If Bethor still exists, he wonders, perhaps he too escaped the Lich King. Still he trusts no stranger, and demands proof: Lillith Nefara, a Scourge agent who wakes at a bloody altar off his island, must be destroyed.', 'quest 366 reward text; quest 409 description'),
(8521, 3, 0, 255, 'Lillith Nefara falls, and Gunther is astonished. He had believed himself the only undead with free will, but now he knows others have broken the Lich King''s domination. He sends a Nether Gem to his old comrade Bethor, so that the two can speak again, for he has much to tell him.', 'quest 409 reward text; quest 411 description'),
(8522, 1, 0, 255, 'When the remains of Gregor, Nissa and Thurman are brought to him, Coleman finds that revenge has a sweet taste. He wonders whether any free will lingered in the Agamands when they were destroyed, and hopes they knew fear before they were smashed into oblivion, though he admits it is a foolish hope.', 'quest 354 reward text; quest 354 required items 2828, 2829, 2830 (remains of Nissa, Gregor, Thurman)'),
(8522, 2, 0, 255, 'When Devlin''s bones are brought to him, Coleman gives them a place on his mantle. If his cold heart can find any warmth, he says, it is in knowing the Agamands are destroyed, for they failed him and his family when the Plague came, and he swears to grind what is left of them under his heel.', 'quest 362 reward text'),
(8522, 3, 0, 255, 'Thurman''s last letter reaches Yvette at last. For a moment she grieves: she begged him to leave the mills with her and her father, but his loyalty to his family was too strong. Then her face grows cold. Regrets are for the weak, she says, and as a Forsaken she has new goals, with no room for love. That life is over.', 'quest 361 reward text'),
(8523, 1, 0, 255, 'Thurman''s undelivered letter tells the truth behind that chatter. Devlin, a mystery to his family since childhood, had warned them that facing the Scourge meant doom. Then he despaired and made a pact with the enemy, murdering two watchmen and letting the undead through a breach, and a third of the defenders were slain. Whatever price he was promised, Thurman was sure it was laced with lies.', 'quest 361 (StartItem 2837 Thurman''s Letter, page_text 214, 252-256)'),
(8527, 1, 0, 255, 'Samuel Fipps is laid to rest at last, his remains buried in Marla''s grave in the first row of the village graveyard. Novice Elreth hopes the two will find peace together. The dead must be respected, she says, for that is one of the ways the Forsaken differ from the Scourge.', 'quest 6395 completion and reward texts; gameobject 178090 Marla''s Grave'),
(8528, 1, 0, 255, 'The messenger, Meven Korgal, is slain at the Crusader camp. Among his scouting reports and orders lies the prize: a map of the dispositions of the Crusade''s field commanders. The orders show a Tirisfal Regional Command answering to the Highlord through three captains, Perrine, Vachon and Melrache.', 'quest 382 reward text; page_text 223, 224 (item 2885 Scarlet Crusade Documents, looted from Meven Korgal 1667 and required by 382)'),
(8528, 2, 0, 255, 'Arren''s papers reach Executor Zygand, and with the Crusade''s positions known he strikes at its leaders. First falls Captain Perrine, cut down with zealots and missionaries of the brigade posted at the ruined tower southwest of Brill. Zygand declares that the death will please the Dark Lady, and vows to herd the Crusade like cattle to its end.', 'quest 427 description (documents Arren provided give their locations); quest 370 description, completion and reward texts'),
(8528, 3, 0, 255, 'Next falls Captain Vachon, slain with his friars at the ruined tower near the Balnir Farmstead, from which they raided southeastern Tirisfal. His death will slow the Crusade''s advance in the glades a good deal, Zygand judges, but other threats loom, and the papers point to one more commander in the north.', 'quest 371 description and reward text'),
(8528, 4, 0, 255, 'Last of all the ruthless Captain Melrache dies with his two bodyguards at the tower in the far north past Faol''s Rest. With the Crusade''s captains in Tirisfal cut down, Zygand praises the ruthless fighters who conquer in the Forsaken''s name, for they bring his people one step closer to defeating Arthas once and for all.', 'quest 372 description and reward text'),
(8529, 1, 0, 255, 'Thurman''s letter tells what the family never lived to tell. His brother Devlin despaired and made a pact with the Scourge. One night he murdered two watchmen and let the undead through a breach, leading them to where many slept, and a third of the defenders died in the ambush. Thurman wrote knowing the family line would end. He did not regret staying with his family, and his last thoughts were for Yvette.', 'page_text 214, 252-256 (Thurman''s Letter, item 2837, given on accepting 361)'),
(8529, 2, 0, 255, 'Coleman takes the Agamand remains with grim satisfaction. Each one brought to him is another of the proud family destroyed, the family whose pride doomed him to undeath, and in their destruction the old mill worker finds what comfort revenge can give.', 'quest 354 description and reward text; quest 362 reward text'),
(8529, 3, 0, 255, 'But the mills threaten all the Forsaken, not Coleman alone. Word of the work reaches Magistrate Sevren, who marks the Agamand Family Crypt for destruction, for there the Scourge commander Captain Dargol has raised the Agamand ancestors by necromancy to use against the Forsaken.', 'quest 355 description and reward text (RewardNextQuest 408); quest 408 description'),
(8529, 4, 0, 255, 'At the family crypt the raised ancestors are cut down and Captain Dargol''s skull is carried to Sevren. The blow will not go unnoticed, the magistrate says, by the Forsaken or by their enemies, and he urges the struggle on until the Lich King himself is driven from Azeroth.', 'quest 408 reward text'),
(8530, 1, 0, 255, 'The half starved zealot cannot resist the gift. Within moments he stammers that he does not feel right, that his mind and flesh are rotting, and he is twisted into the shape of a ghoul before he falls dead. A simple pumpkin, as Johaan promised, has become an agent of the Dark Lady.', 'quest 407 description, completion and reward texts; creature_text 1931; smart_scripts 193100 (Ghoul Form, then death)'),
(8530, 2, 0, 255, 'With the venom added and the brew boiled down, Johaan''s deadly new agent is ready to try. He mixes a special drink for a dwarven mountaineer the Deathguard have just captured, one that holds, he says, a subtle hint of what the Dark Lady has planned for the rest of Azeroth.', 'quest 369 reward text; quest 492 description'),
(8530, 3, 0, 255, 'The mountaineer, still boasting that the Steam Tank Brigade will come to rescue him, takes the drink gladly and raises it in a defiant toast. Moments later he falls dead. Johaan sends his findings on to his colleagues of the Society at the Sepulcher in Silverpine Forest, so that their joined work might one day give the Dark Lady her New Plague.', 'quest 492 completion and reward texts; creature_text 2211; smart_scripts 221100 (kill self); quest 445 description'),
(8531, 1, 0, 255, 'Bethor opens the book and is astonished: it belongs to Gunther Arcanus, his friend and comrade before the Plague. Long ago the two of them studied among the Kirin Tor of Dalaran with Thule Ravenclaw, now a necromancer of the Scourge. Bethor enchants the book so that it will show Gunther he too is free of the Lich King, and has it carried back to the island.', 'quest 357 reward text; quest 366 description'),
(8531, 2, 0, 255, 'Gunther recognizes Bethor''s enchantment and wonders whether his old friend truly escaped. Before he believes anything he wants proof that the thief is no Scourge slave, so the agent must light a Candle of Beckoning on a bloody altar off the island''s southern shore and destroy Lillith Nefara when she wakes.', 'quest 366 reward text; quest 409 description'),
(8531, 3, 0, 255, 'Lillith Nefara falls. Gunther had believed he was the only undead with free will, and now he knows others have broken the Lich King''s domination. He gives the agent a Nether Gem to carry to Bethor, so that the two old friends can speak again.', 'quest 409 reward text; quest 411 description'),
(8531, 4, 0, 255, 'The Nether Gem reaches Bethor in the Undercity, and with it word that Gunther will join the Forsaken. It is a great deed, Bethor declares. The Forsaken have won a powerful ally in the lich of Brightwater Lake, and the Dark Lady will be told of it.', 'quest 411 reward text'),
(8532, 1, 0, 255, 'The Scourge are mistaken, Sevren declares, if they think those corpses can be turned against the Forsaken. The ichor drained from the Rot Hide slaves goes to the apothecaries of the Society, for it may hold secrets the Forsaken can use against the Scourge.', 'quest 358 reward text'),
(8532, 2, 0, 255, 'Maggot Eye is dead, and his paw is laid before Executor Zygand. The town of Brill counts his crimes avenged, and Zygand hopes the deed sends a clear message to all who would bring harm to the Forsaken.', 'quest 398 reward text'),
(8532, 3, 0, 255, 'Gordo comes back with gloom weed, which is no use at all. Junior Apothecary Holland fumes that the mindless mass of flesh is out picking the wrong plants and drawing who knows how many helpers into the same mistake, and he sends a more capable one after what he truly needs: doom weed from the mass graves.', 'quest 5481 reward text; quest 5482 description');
